/* Render safety: text is escaped; links may only use approved schemes. */
const safeText = value => String(value == null ? '' : value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl = (value, fallback='#') => { try { const u=new URL(String(value), location.href); return /^(https?:|tel:|mailto:|kakaomap:|nmap:|tmap:)$/.test(u.protocol) ? u.href : fallback; } catch (_) { return fallback; } };

// 탭을 바꿔도 화면이 맨 위로 튀지 않게: 아래로 내려와 있었다면 탭 메뉴 바로 아래에서 새 페이지가 시작되게 맞춘다
const COMPACT_TABS = new Set(["course","favs","coupons","my","more","journal"]);
const PAGE_TITLES = { course:"일정 · 내 코스", favs:"찜", coupons:"쿠폰북", my:"마이페이지", more:"더보기", journal:"여행 기록" };
function keepTabPos(){
  if (document.body.classList.contains("compact")){ window.scrollTo({ top:0, behavior:"instant" }); return; }
  const bar = document.querySelector(".tabbar"), main = document.querySelector("main.inner");
  if (!bar || !main) return;
  const target = Math.max(0, main.getBoundingClientRect().top + window.scrollY - bar.offsetHeight);
  if (window.scrollY > target) window.scrollTo({ top: target, behavior: "instant" });
}
