PLACES.forEach(p=>{ if (!p.region) p.region = "gangneung"; });
function enrichWeatherPlaces(list){
  const target = list || PLACES;
  const indoorCats = new Set(["카페", "맛집", "소품샵"]);
  target.forEach(p => {
    if (!p.seasons) {
      p.seasons = p.season === "winterRisk" ? ["봄", "여름", "가을"] : ["봄", "여름", "가을", "겨울"];
    }
    if (!p.weather) {
      const text = `${p.cat||""} ${p.sig||""} ${p.closedNote||""} ${p.tip||""} ${(p.tags||[]).join(" ")}`;
      const isIndoor = (p.tags||[]).includes("실내") || indoorCats.has(p.cat);
      const windSensitive = !isIndoor && /강풍|바다|해변|케이블카|하늘자전거|짚라인|레일바이크|부채길|서핑|고원/.test(text);
      const rainOk = isIndoor || (!windSensitive && !/우천|기상|호우|계곡|트레킹|야외/.test(text));
      p.weather = { indoor: isIndoor, rainOk, windSensitive };
    }
    if (!p.verified) {
      const needsCheck = /확인|엇갈/.test(`${p.hours||""} ${p.closedNote||""}`);
      p.verified = { checkedAt: "2026-11", status: needsCheck ? "check_hours" : "active" };
    }
  });
  target.forEach(p => {
    if (Array.isArray(p.altIndoorIds)) return;
    if (p.weather.rainOk && !p.weather.windSensitive) { p.altIndoorIds = []; return; }
    p.altIndoorIds = PLACES
      .filter(x => x.id !== p.id && x.region === p.region && x.weather && x.weather.indoor && x.lat && x.lng)
      .sort((a, b) => Math.hypot(a.lat - p.lat, a.lng - p.lng) - Math.hypot(b.lat - p.lat, b.lng - p.lng))
      .slice(0, 3)
      .map(x => x.id);
  });
}
