const seasonOf = m =>Object.keys(SEASONS).find(k=>SEASONS[k].months.includes(m)) || "겨울";
const seasonPick = p => { const ss = SEASONS[seasonOf(tripDay().getMonth()+1)]; const x = ss.picks.find(r=>r[0]===p.id); return x ? x : null; };
