const FOOD_SUBS = ["한식","해산물·회","중식","일식","양식","분식·치킨","카페·디저트","기타"];
// 술 마실 수 있는 곳(술집·포차·이자카야·바·막걸리집 등). 요리 종류와 겹쳐도 되므로 따로 판단한다.
const BAR_RE = /포차|포장마차|실내마차|주점|술집|이자카야|호프|펍|\bpub\b|와인바|위스키|칵테일|막걸리|노가리|소주방|선술집|하이볼|브루어리|브루잉|수제맥주|생맥주/i;
function isBar(p){ return (p.tags||[]).includes("술집") || BAR_RE.test([p.name, p.sig, ...(p.tags||[])].join(" ")); }
function foodSub(p){
  if (p._fs) return p._fs;
  const t = [p.name, p.sig, ...(p.tags||[])].join(" ").replace("대표 메뉴는 현장 확인","");
  for (const [k, re] of FOOD_RULES) if (re.test(t)) return (p._fs = k);
  return (p._fs = "기타");
}

