// ───────── 운영자 장소 관리: 직접 추가·수정·숨기기·순서 ─────────
// 운영자가 바꾼 내용은 페이지 안의 <script id="ownerData">에 들어가고, '저장하고 공개'로 이 페이지 자체를 새 버전으로 저장한다.
// 그래서 로그인하지 않은 방문자와 휴대폰 앱(APK)에서도 똑같이 보인다.
// 앱(APK)에서는 GitHub 저장소의 web/owner.json 이 운영 데이터다(앱 운영자 모드에서 저장). 받아 둔 것이 있으면 그걸 쓴다.
const GH = { repo:"flyaranaby-collab/gangwon-travel", branch:"main", raw:"https://raw.githubusercontent.com/flyaranaby-collab/gangwon-travel/main/web/" };
// 운영 데이터는 rev(저장 시각)가 가장 큰 것을 쓴다: 페이지에 든 것 / 이 기기에 받아 둔 것 / GitHub 최신본.
// 그래서 GitHub 쪽 캐시가 늦게 풀려 옛 데이터가 와도 새로 저장한 내용을 덮어쓰지 않는다.
const ownerRev = o => (o && +o.rev) || 0;
const OWNER = (()=>{ let o = {};
  try { o = JSON.parse(document.getElementById("ownerData").textContent) || {}; } catch(_) {}
  try { const c = JSON.parse(localStorage.getItem("gw_owner") || "null");
    if (c && c.v && (ownerRev(c) > ownerRev(o) || (window.APK_BUILD && !ownerRev(o) && !ownerRev(c)))) o = c; } catch(_) {}
  return o; })();
OWNER.photos = OWNER.photos && typeof OWNER.photos==="object" && !Array.isArray(OWNER.photos) ? OWNER.photos : {};
OWNER.edits = OWNER.edits && typeof OWNER.edits==="object" && !Array.isArray(OWNER.edits) ? OWNER.edits : {};
// 운영자가 정한 '○○, 누구와 가기 좋은 곳' 순서: picks["지역|동행"] = [장소 id, …]
OWNER.picks = OWNER.picks && typeof OWNER.picks==="object" && !Array.isArray(OWNER.picks) ? OWNER.picks : {};
// 수익 설정(운영자가 앱·웹에서 직접 관리): 문의 연락처, 자사 홍보 배너, 제휴 예약 링크, 광고 가게, 제휴 쿠폰
const BIZ0 = { contact:{ kakao:"", phone:"", email:"" },
  promo:{ on:false, title:"강릉 아라나비 짚라인 · 바다하늘자전거", text:"강릉 바다 위를 나는 짚라인과 바다하늘자전거. 수첩 사용자에게 추천해요.", url:"", place:"skybike" },
  partner:{ stay:"", ticket:"" }, sponsored:[], coupons:[] };
OWNER.biz = (()=>{ const b = OWNER.biz && typeof OWNER.biz==="object" ? OWNER.biz : {};
  return { contact:{ ...BIZ0.contact, ...(b.contact||{}) }, promo:{ ...BIZ0.promo, ...(b.promo||{}) }, partner:{ ...BIZ0.partner, ...(b.partner||{}) },
    sponsored: Array.isArray(b.sponsored) ? b.sponsored : [], coupons: Array.isArray(b.coupons) ? b.coupons : [],
    ...(typeof b.sampleCoupons === "boolean" ? { sampleCoupons:b.sampleCoupons } : {}) }; })();
OWNER.places = Array.isArray(OWNER.places) ? OWNER.places : [];
OWNER.hidden = Array.isArray(OWNER.hidden) ? OWNER.hidden : [];
OWNER.order = Array.isArray(OWNER.order) ? OWNER.order : [];
OWNER.deleted = Array.isArray(OWNER.deleted) ? OWNER.deleted.filter(x=>x && x.id) : [];   // 운영자가 지운 장소: [{id,name,region}]
function normPlace(p){
  const r = REG[p.region] ? p.region : "gangneung";
  return { id:p.id, region:r, name:String(p.name||"").trim(), cat:p.cat||"맛집", area:p.area||REG[r].name,
    lat:+p.lat || REG[r].lat, lng:+p.lng || REG[r].lng, sig:p.sig||"", hours:p.hours||"현장 확인", fee:p.fee||"현장 확인",
    closed:Array.isArray(p.closed)?p.closed.map(Number):[], closedNote:p.closedNote||"", tip:p.tip||"",
    who:p.who||{친구:2,연인:2,가족:2,혼자:2}, tags:Array.isArray(p.tags)?p.tags:[], link:p.link||"", mapq:p.mapq||"", addr:p.addr||"", custom:true };
}
OWNER.places = OWNER.places.map(normPlace);
OWNER.places.forEach(p=>{ PLACES.push(p); if (!META[p.id]) META[p.id] = { o:null, c:null, stay:60, cost:0 }; });
const ALL_PLACES = PLACES.slice();
const HIDDEN = new Set(OWNER.hidden);
const DELETED = new Set(OWNER.deleted.map(x=>x.id));
function applyOwner(){
  const keep = PLACES.filter(p=>!ALL_PLACES.includes(p));          // 관광공사 등 나중에 더해진 장소는 그대로 둔다
  PLACES.length = 0;
  ALL_PLACES.forEach(p=>{ if (!HIDDEN.has(p.id) && !DELETED.has(p.id)) PLACES.push(p); });
  keep.forEach(p=>{ if (!DELETED.has(p.id)) PLACES.push(p); });
  if (typeof LODGING !== "undefined") for (let i=LODGING.length-1;i>=0;i--) if (DELETED.has(LODGING[i].id)) LODGING.splice(i,1);
  if (typeof enrichWeatherPlaces === "function") enrichWeatherPlaces();
}
applyOwner();
const orderIdx = id => { const i = OWNER.order.indexOf(id); return i<0 ? 1e9 : i; };
const PM = { region:"gangneung", cat:"전체", edit:null, dirty:false, msg:"", err:"", busy:false };
// 변경이 생기면 표시하고, 앱에서는 1초 뒤 자동 저장한다(저장 버튼을 깜빡해도 사라지지 않게)
let pmTimer = null;
function pmChanged(){
  PM.dirty = true;
  if (window.APK_BUILD && ghToken()){ clearTimeout(pmTimer); pmTimer = setTimeout(()=>{ if (!PM.busy && PM.dirty) pmSave(); }, 1000); }
}
const pmNoAddr = () => [...ALL_PLACES, ...PLACES.filter(p=>p.source==="kto")].filter(p=>!DELETED.has(p.id) && !String(p.addr||"").trim());
const pmList = () => ((PM.nophoto || PM.kto || PM.noaddr) ? [...ALL_PLACES, ...PLACES.filter(p=>p.source==="kto")] : ALL_PLACES)
  .filter(p=>!DELETED.has(p.id) && (PM.noaddr && PM.region==="all" || p.region===PM.region) && (PM.cat==="전체"||p.cat===PM.cat) && (!PM.nophoto || !photoFor(p)) && (!PM.noaddr || !String(p.addr||"").trim()))
  .sort((a,b)=>orderIdx(a.id)-orderIdx(b.id) || (b.who.가족+b.who.친구)-(a.who.가족+a.who.친구) || a.name.localeCompare(b.name));
function pmMove(id, dir){
  const list = pmList().map(p=>p.id), i = list.indexOf(id), j = i+dir;
  if (i<0 || j<0 || j>=list.length) return;
  [list[i], list[j]] = [list[j], list[i]];
  const rest = OWNER.order.filter(x=>!list.includes(x));
  OWNER.order = [...list, ...rest];
  pmChanged();
}
function placeManager(){
  const list = pmList(), e = PM.edit;
  const opt = (arr, cur) => arr.map(([v,t])=>`<option value="${esc(v)}" ${v===cur?"selected":""}>${esc(t)}</option>`).join("");
  const regs = REGIONS.map(r=>[r.id, r.name]), cats = [...new Set([...CATS.filter(c=>c!=="전체"), ...(e && e.cat ? [e.cat] : [])])].map(c=>[c,c]);
  const WDS = ["일","월","화","수","목","금","토"];
  const form = e ? `
    <form class="revform pmform" id="pmForm" autocomplete="off">
      <h3>${e.id ? "장소 수정" : "새 장소 추가"}</h3>
      ${e.id && !e.custom ? `<p class="meta">${e.source==="kto"?"관광공사 등록 장소예요. ":"기본 장소예요. "}바꾼 항목만 저장되고, 아래 ‘원래대로’로 되돌릴 수 있어요.</p>` : ""}
      <div class="formgrid">
        <label>이름<input id="pmName" value="${esc(e.name||"")}" required placeholder="예: 남애항 어촌횟집"></label>
        <label>분류<select id="pmCat">${opt(cats, e.cat||"맛집")}</select></label>
        <label>지역<select id="pmRegion">${opt(regs, e.region||PM.region)}</select></label>
        <label>동네<input id="pmArea" value="${esc(e.area||"")}" placeholder="예: 주문진"></label>
        <label>시그니처(대표 메뉴·볼거리)<input id="pmSig" value="${esc(e.sig||"")}" placeholder="예: 가자미 어죽, 물회"></label>
        <label>운영시간<input id="pmHours" value="${esc(e.hours||"")}" placeholder="예: 10:00~20:00"></label>
        <label>요금·가격<input id="pmFee" value="${esc(e.fee||"")}" placeholder="예: 1만 원대"></label>
        <label>휴무 메모<input id="pmCnote" value="${esc(e.closedNote||"")}" placeholder="예: 명절 당일 휴무"></label>
        <label>태그(쉼표로 구분)<input id="pmTags" value="${esc((e.tags||[]).join(", "))}" placeholder="예: 현지인맛집, 아침"></label>
        <label>지도 위도(선택)<input id="pmLat" inputmode="decimal" value="${e.lat&&e.id?esc(e.lat):""}" placeholder="비우면 지역 중심"></label>
        <label>지도 경도(선택)<input id="pmLng" inputmode="decimal" value="${e.lng&&e.id?esc(e.lng):""}" placeholder="예: 128.90"></label>
        <label>관련 링크(선택)<input id="pmLink" type="url" value="${esc(e.link||"")}" placeholder="https://"></label>
        <label>주소(선택)<input id="pmAddr" value="${esc(e.addr||"")}" placeholder="예: 강원특별자치도 강릉시 ○○로 12"></label>
        <label>지도 검색어(입구·안내센터)<input id="pmMapq" value="${esc(e.mapq||"")}" placeholder="예: 강릉중앙시장 정문, 경포해변 관광안내소"></label>
      </div>
      <div class="row"><span class="meta">정기 휴무</span>${WDS.map((w,i)=>`<label class="pmday"><input type="checkbox" id="pmDay${i}" ${(e.closed||[]).includes(i)?"checked":""}> ${w}</label>`).join("")}</div>
      <label>팁<textarea id="pmTip" placeholder="방문자에게 알려 줄 팁">${esc(e.tip||"")}</textarea></label>
      <div class="row"><button class="btn" type="submit">${e.id ? "수정 반영" : "목록에 추가"}</button><button class="btn ghost" type="button" data-pm="cancel">취소</button>${e.id && !e.custom && OWNER.edits[e.id] ? `<button class="btn ghost" type="button" data-pm="revert" data-id="${esc(e.id)}">원래대로</button>` : ""}</div>
      <p class="meta">위도·경도는 네이버·카카오 지도에서 장소를 길게 눌러 확인할 수 있어요. 비워 두면 지역 중심에 표시돼요.</p>
    </form>` : "";
  return `<section class="revbox pm" aria-label="장소 관리">
    <h2>장소 관리</h2>
    <p>장소를 직접 추가하거나, 숨기거나, 위·아래 버튼으로 보이는 순서를 정할 수 있어요. 바꾼 뒤 <b>저장하고 공개</b>를 누르면 ${window.APK_BUILD ? "앱을 쓰는 모든 휴대폰에 반영돼요(다른 휴대폰은 앱을 다시 열면, 길게는 5분 뒤)." : "링크로 들어오는 모든 사람에게 반영돼요."}</p>
    <div class="filters">
      <select id="pmRegionSel" aria-label="관리할 지역">${opt(PM.noaddr ? [["all","전체 지역"], ...regs] : regs, PM.region)}</select>
      <select id="pmCatSel" aria-label="관리할 분류">${opt([["전체","전체 분류"], ...cats], PM.cat)}</select>
      <button class="btn" data-pm="new">+ 새 장소</button>
      <label class="pmday"><input type="checkbox" id="pmNoPhoto" ${PM.nophoto?"checked":""}> 사진 없는 곳만</label>
      <label class="pmday"><input type="checkbox" id="pmKto" ${PM.kto?"checked":""}> 관광공사 장소도 보기</label>
      <label class="pmday"><input type="checkbox" id="pmNoAddr" ${PM.noaddr?"checked":""}> 📍 주소 없는 곳만 (${pmNoAddr().length})</label>
    </div>
    ${PM.noaddr ? `<p class="meta">주소가 확인되지 않은 장소 ${list.length}곳이에요${PM.region==="all"?" (전체 지역)":""}. ‘수정’을 눌러 주소 칸에 정확한 주소를 넣고 저장해 주세요. 관광공사·구글 지도에서 이름과 위치가 맞는 곳을 찾지 못해 비워 둔 곳이에요. 주소는 카드와 상세 화면에 그대로 보이니, 간판·지도로 확인한 주소만 넣어 주세요.</p>` : ""}
    ${PM.nophoto ? `<p class="meta">사진이 없는 장소 ${list.length}곳이에요. ‘사진 등록’을 누르면 휴대폰 사진첩이나 카메라에서 고를 수 있어요. 직접 찍었거나 사용 허락을 받은 사진만 올려 주세요.</p>` : ""}
    ${form}
    <ol class="pmlist">${list.map((p,i)=>`<li class="${HIDDEN.has(p.id)?"off":""}">
      <span class="pmno">${i+1}</span>
      <span class="pmnm"><b>${esc(p.name)}</b><small>${esc(p.cat)} · ${esc(p.area)}${p.custom?" · 직접 추가":""}${p.source==="kto"?" · 관광공사":""}${HIDDEN.has(p.id)?" · 숨김":""} · ${photoFor(p)?"사진 있음":"사진 없음"} · ${String(p.addr||"").trim() ? esc(String(p.addr).replace(/^강원(특별자치)?도\s*/,"")) : "📍 주소 없음"}</small><span class="pmph">${photoCtl(p)}</span></span>
      <span class="pmctl">
        <button data-pm="up" data-id="${p.id}" ${i===0?"disabled":""} aria-label="위로">▲</button>
        <button data-pm="down" data-id="${p.id}" ${i===list.length-1?"disabled":""} aria-label="아래로">▼</button>
        <button data-pm="hide" data-id="${p.id}">${HIDDEN.has(p.id)?"보이기":"숨기기"}</button>
        <button data-pm="edit" data-id="${p.id}">수정</button><button data-pm="del" data-id="${p.id}">삭제</button>
      </span></li>`).join("") || `<li class="empty">이 지역·분류에는 장소가 없어요.</li>`}</ol>
    ${OWNER.deleted.length ? `<details class="playbook"><summary>삭제한 장소 ${OWNER.deleted.length}곳 (눌러서 복구)</summary><ul class="pmdel">${OWNER.deleted.map(x=>`<li>${esc(x.name)}${x.region&&REG[x.region]?` · ${esc(REG[x.region].name)}`:""} <button class="linkbtn" data-pm="undel" data-id="${esc(x.id)}">복구</button></li>`).join("")}</ul></details>` : ""}
    ${OSYNC.pending ? `<p class="okline">다른 곳에서 저장한 더 새로운 운영 데이터가 있어요. 지금 작업을 저장한 뒤 앱(페이지)을 다시 열면 합쳐져요.</p>` : ""}
    <div class="pmsave">
      <button class="btn" type="button" data-pm="save" ${PM.busy?"disabled":""}>${PM.busy?"저장하는 중…":"저장하고 공개"}</button>
      <button class="btn ghost" type="button" data-pm="reset" ${PM.busy?"disabled":""}>바꾼 내용 되돌리기</button>
      ${PM.dirty?`<span class="meta">저장하지 않은 변경이 있어요.</span>`:""}
      ${PM.msg?`<span class="okline">${esc(PM.msg)}</span>`:""}${PM.err?`<span class="errline">${esc(PM.err)}</span>`:""}
    </div>
    <details class="playbook"><summary>저장이 안 될 때 (운영 데이터 복사)</summary>
      <p class="meta">아래 내용을 복사해 Claude에게 붙여 넣으면 대신 반영해 드려요.</p>
      <textarea id="pmExport" readonly>${esc(ownerJson())}</textarea>
    </details>
  </section>`;
}
const ownerJson = () => JSON.stringify({ v:1, rev:OWNER.rev||0, places:ALL_PLACES.filter(p=>p.custom).map(({custom, ...rest})=>rest), hidden:[...HIDDEN], deleted:OWNER.deleted, order:OWNER.order, photos:OWNER.photos, edits:OWNER.edits, picks:OWNER.picks, biz:OWNER.biz, auth:OWNER.auth||null });
// 장소 삭제: 직접 추가한 장소는 목록에서 아예 지우고, 기본·관광공사 장소는 ‘삭제 목록’에 올려 업데이트 때도 다시 나오지 않게 한다
function pmDelete(id){
  const t = ALL_PLACES.find(p=>p.id===id) || PLACES.find(p=>p.id===id) || (typeof LODGING!=="undefined" && LODGING.find(p=>p.id===id));
  if (t && t.custom){ const i = ALL_PLACES.findIndex(p=>p.id===id); if (i>=0) ALL_PLACES.splice(i,1); }
  else if (t && !DELETED.has(id)){ OWNER.deleted.push({ id, name:t.name, region:t.region||"" }); DELETED.add(id); }
  OWNER.order = OWNER.order.filter(x=>x!==id); HIDDEN.delete(id);
  state.course = state.course.filter(x=>x!==id); Object.keys(state.courses||{}).forEach(k=>{ if (Array.isArray(state.courses[k])) state.courses[k] = state.courses[k].filter(x=>x!==id); });
  state.favs = state.favs.filter(x=>x!==id);
  applyOwner(); pmChanged(); save();
}
function pmRerender(){ renderOps(); renderGrid(); renderTop(); }
function pmReadForm(){
  const v = id => (document.getElementById(id)?.value || "").trim();
  const closed = [0,1,2,3,4,5,6].filter(i=>document.getElementById("pmDay"+i)?.checked);
  const days = ["일","월","화","수","목","금","토"];
  const base = PM.edit && PM.edit.id ? PM.edit : {};
  return normPlace({ ...base, id: base.id || ("c-" + Date.now().toString(36)), name:v("pmName"), cat:v("pmCat"), region:v("pmRegion"), area:v("pmArea"),
    sig:v("pmSig"), hours:v("pmHours"), fee:v("pmFee"), tip:v("pmTip"), link:v("pmLink"), mapq:v("pmMapq"), addr:v("pmAddr"),
    closed, closedNote: v("pmCnote") || (closed.length ? `매주 ${closed.map(i=>days[i]).join("·")}요일 휴무` : ""),
    tags: v("pmTags").split(/[,，]/).map(s=>s.trim()).filter(Boolean),
    lat: v("pmLat"), lng: v("pmLng") });
}
// 이 페이지의 원본을 가져와 ownerData 부분만 바꿔 새 버전으로 저장한다
async function pmSourceHtml(){
  for (const u of ["index.html", location.pathname]){
    try {
      const r = await fetch(u, { cache:"no-store" }); if (!r.ok) continue;
      let t = await r.text(); const i = t.search(/<!doctype html/i); if (i<0) continue;
      t = t.slice(i);
      if (/<script id="ownerData" type="application\/json">/.test(t) && t.includes('id="tab-places"')) return t;
    } catch(_) {}
  }
  return null;
}
async function pmSave(){
  PM.busy = true; PM.err = PM.msg = ""; renderOps();
  if (window.APK_BUILD){
    try { await ghSaveOwner(); PM.dirty = false; PM.msg = "저장했어요. 다른 휴대폰은 앱을 다시 열면 반영돼요(길게는 5분)."; }
    catch(e){ PM.err = ghErrText(e) + " 바꾼 내용은 이 휴대폰에 남아 있으니 ‘저장하고 공개’를 다시 눌러 주세요."; }
    PM.busy = false; renderOps(); if (HOTED.open) renderPlaces(); renderGrid(); return;
  }
  // 웹: GitHub 토큰을 연결해 두었으면 앱용 운영 데이터도 같이 저장한다
  let ghOk = null;
  if (ghToken()){ try { await ghSaveOwner(); ghOk = true; } catch(e){ ghOk = false; } }
  else OWNER.rev = Date.now();
  try {
    const art = await useCap("artifact");
    if (!art) throw { code:"not_granted" };
    const src = await pmSourceHtml();
    if (!src) throw { code:"no_source" };
    const data = ownerJson().replace(/</g, "\\u003c");
    const html = src.replace(/<script id="ownerData" type="application\/json">[\s\S]*?<\/script>/, ()=>`<script id="ownerData" type="application/json">${data}<\/script>`);
    await art.publish(html);
    PM.dirty = false; PM.msg = "저장했어요. 잠시 뒤 새 버전으로 다시 열려요." + (ghOk===true ? " 앱에도 반영했어요." : ghOk===false ? " (앱 반영은 실패: GitHub 토큰을 확인하세요)" : "");
  } catch(e) {
    const c = e && e.code;
    PM.err = c==="conflict" ? "그사이 페이지가 새로 저장되어 다시 불러와요. 변경을 다시 해 주세요."
      : (c==="not_writer"||c==="not_granted"||c==="not_declared") ? "이 화면에서는 저장할 수 없어요. 페이지 주인 계정으로 연 화면에서 저장하세요."
      : c==="no_source" ? "페이지 원본을 불러오지 못했어요. 아래 '운영 데이터 복사'를 Claude에게 보내 주세요."
      : c==="rate_limited" ? "저장이 너무 잦아요. 잠시 뒤 다시 눌러 주세요."
      : "저장하지 못했어요. 잠시 뒤 다시 시도하거나 운영 데이터를 복사해 Claude에게 보내 주세요.";
  }
  PM.busy = false; renderOps();
}
document.addEventListener("change", e=>{
  if (e.target.id==="pmRegionSel"){ PM.region = e.target.value; PM.edit = null; renderOps(); }
  if (e.target.id==="pmCatSel"){ PM.cat = e.target.value; renderOps(); }
  if (e.target.id==="pmNoPhoto"){ PM.nophoto = e.target.checked; renderOps(); }
  if (e.target.id==="pmNoAddr"){ PM.noaddr = e.target.checked; if (PM.noaddr) PM.region = "all"; else if (PM.region==="all") PM.region = "gangneung"; renderOps(); }
  if (e.target.id==="pmKto"){ PM.kto = e.target.checked; renderOps(); }
});
document.addEventListener("click", e=>{
  const b = e.target.closest("[data-pm]"); if (!b) return;
  const a = b.dataset.pm, id = b.dataset.id; PM.msg = PM.err = "";
  if (a==="new"){ PM.edit = { region:PM.region==="all" ? "gangneung" : PM.region, cat: PM.cat==="전체" ? "맛집" : PM.cat }; renderOps(); document.getElementById("pmName")?.focus(); return; }
  if (a==="cancel"){ PM.edit = null; renderOps(); return; }
  if (a==="up" || a==="down"){ pmMove(id, a==="up" ? -1 : 1); pmRerender(); return; }
  if (a==="hide"){ HIDDEN.has(id) ? HIDDEN.delete(id) : HIDDEN.add(id); applyOwner(); pmChanged(); pmRerender(); return; }
  if (a==="edit"){ const t = byId(id); if (!t) return; if (!PM.noaddr) PM.region = t.region; PM.edit = { ...t }; renderOps(); document.getElementById("pmForm")?.scrollIntoView({ block:"start" }); return; }
  if (a==="revert"){ const t = byId(id); if (!t || !OWNER.edits[id]) return;
    delete OWNER.edits[id]; if (t.__orig) Object.assign(t, t.__orig); PM.edit = null; pmChanged(); PM.msg = `‘${t.name}’을(를) 원래 정보로 되돌렸어요. 저장해야 공개돼요.`; pmRerender(); return; }
  if (a==="del"){
    if (b.dataset.sure!=="1"){ b.dataset.sure = "1"; b.textContent = "한 번 더 누르면 삭제"; return; }
    pmDelete(id); PM.msg = "삭제했어요. ‘저장하고 공개’를 눌러야 다른 휴대폰에도 반영돼요."; pmRerender(); return; }
  if (a==="undel"){
    OWNER.deleted = OWNER.deleted.filter(x=>x.id!==id); DELETED.delete(id); applyOwner(); pmChanged();
    PM.msg = "복구했어요. 저장하고 공개한 뒤 앱을 다시 열면 목록에 다시 나와요."; pmRerender(); return; }
  if (a==="save"){ if (PM.edit && document.getElementById("pmForm")){ PM.err = "열려 있는 수정 양식의 ‘수정 반영’을 먼저 눌러 주세요."; renderOps(); document.getElementById("pmForm")?.scrollIntoView({ block:"start" }); return; }
    pmSave(); return; }
  if (a==="reset"){
    if (PM.dirty && !confirm("저장하지 않은 변경을 버리고 마지막으로 공개한 상태로 되돌릴까요?")) return;
    if (window.APK_BUILD){ try { localStorage.removeItem("gw_owner"); } catch(_) {} }   // 앱: GitHub에 공개된 운영 데이터를 다시 받는다
    location.reload(); return; }
});
document.addEventListener("submit", e=>{
  if (e.target.id!=="pmForm") return; e.preventDefault();
  const p = pmReadForm();
  if (!p.name){ PM.err = "이름을 적어 주세요."; renderOps(); return; }
  const target = byId(p.id);
  if (target && !target.custom) {      // 기본·관광공사 장소: 바꾼 항목만 저장
    const ed = {}; EDIT_KEYS.forEach(k=>{ const o = (target.__orig && k in target.__orig) ? target.__orig[k] : target[k]; if (JSON.stringify(p[k]) !== JSON.stringify(o==null ? "" : o)) ed[k] = p[k]; });
    if (Object.keys(ed).length) OWNER.edits[p.id] = ed; else delete OWNER.edits[p.id];
    applyEdits(); if (!Object.keys(ed).length && target.__orig) Object.assign(target, target.__orig);
    PM.edit = null; PM.dirty = true; PM.msg = `‘${p.name}’ 정보를 고쳤어요. 저장하는 중…`;
    applyOwner(); pmRerender(); renderTop(); pmSave(); return;
  }
  const i = ALL_PLACES.findIndex(x=>x.id===p.id);
  if (i>=0) Object.assign(ALL_PLACES[i], p); else { ALL_PLACES.push(p); META[p.id] = { o:null, c:null, stay:60, cost:0 }; }
  if (!OWNER.order.includes(p.id)){ const list = pmList().map(x=>x.id).filter(x=>x!==p.id); OWNER.order = [p.id, ...list, ...OWNER.order.filter(x=>!list.includes(x) && x!==p.id)]; }
  PM.region = p.region; PM.edit = null; PM.dirty = true; PM.msg = `‘${p.name}’을(를) 목록 맨 위에 넣었어요. 저장하는 중…`;
  applyOwner(); pmRerender(); pmSave();
});

// ───────── 앱(APK) 운영자 모드 ─────────
// 운영자가 앱에서 바꾼 장소·순서·사진은 GitHub 저장소(web/owner.json, web/photos/u-*.jpg)에 저장되고,
// 모든 휴대폰 앱이 켤 때 owner.json 을 받아 반영한다. 토큰은 운영자 휴대폰에만 저장된다.
let sessionGhToken = ""; const ghToken = () => sessionGhToken;
async function ghApi(path, opt = {}, token){
  const r = await fetch("https://api.github.com/repos/" + GH.repo + path, { ...opt, cache:"no-store",
    headers:{ "Accept":"application/vnd.github+json", "Authorization":"Bearer " + (token || ghToken()), ...(opt.body ? { "Content-Type":"application/json" } : {}) } });
  if (!r.ok){ const e = new Error("HTTP " + r.status); e.status = r.status; throw e; }
  return r.status===204 ? null : r.json();
}
async function ghPut(path, b64, msg){
  let sha; try { sha = (await ghApi("/contents/" + path + "?ref=" + GH.branch)).sha; } catch(e){ if (e.status!==404) throw e; }
  return ghApi("/contents/" + path, { method:"PUT", body:JSON.stringify({ message:msg, content:b64, branch:GH.branch, ...(sha ? { sha } : {}) }) });
}
const b64utf8 = t => btoa(unescape(encodeURIComponent(t)));
const ghErrText = e => (e && (e.status===401 || e.status===403)) ? "토큰이 맞지 않거나 쓰기 권한이 없어요. 운영자 로그아웃 후 토큰을 다시 넣어 주세요."
  : (e && e.status===409) ? "그사이 다른 곳에서 저장했어요. 앱을 다시 열고 한 번 더 해 주세요."
  : "저장하지 못했어요. 인터넷 연결을 확인하고 다시 눌러 주세요.";
async function ghSaveOwner(){
  const prev = OWNER.rev; OWNER.rev = Date.now();
  const data = ownerJson();
  try { await ghPutOwner(data); } catch(e){ OWNER.rev = prev; throw e; }
  try { localStorage.setItem("gw_owner", data); } catch(_) {}
}
async function ghPutOwner(data){
  await ghPut("web/owner.json", b64utf8(data), "운영자: 장소·순서·사진 변경");
}
// 사진은 긴 변 1280px JPEG 로 줄여 올린다(데이터 절약)
async function shrinkJpeg(file, max = 1280, q = .82){
  const url = URL.createObjectURL(file);
  try {
    const img = await new Promise((ok, no)=>{ const i = new Image(); i.onload = ()=>ok(i); i.onerror = no; i.src = url; });
    const k = Math.min(1, max / Math.max(img.naturalWidth, img.naturalHeight));
    const c = document.createElement("canvas"); c.width = Math.round(img.naturalWidth*k); c.height = Math.round(img.naturalHeight*k);
    c.getContext("2d").drawImage(img, 0, 0, c.width, c.height);
    return c.toDataURL("image/jpeg", q).split(",")[1];
  } finally { URL.revokeObjectURL(url); }
}
async function ghUploadPhoto(id, file){
  const credit = ((window.prompt && window.prompt("사진 출처를 적어 주세요 (예: 직접 촬영, 가게 제공)", "직접 촬영")) || "직접 촬영").trim();
  const b64 = await shrinkJpeg(file);
  const name = "u-" + id.replace(/[^a-z0-9_-]/gi, "_") + ".jpg";
  await ghPut("web/photos/" + name, b64, "운영자: 사진 등록 " + id);
  OWNER.photos[id] = { url: GH.raw + "photos/" + name + "?v=" + Date.now().toString(36), credit: "사진: " + credit };
  await ghSaveOwner();
}
