// 제휴 쿠폰 이미지: 앱(또는 GitHub 연결된 웹)은 GitHub에, 웹 주인 화면은 아티팩트 저장소에 올린다
async function bizCouponImg(cid, file){
  try {
    if (ghToken()){ const b64 = await shrinkJpeg(file, 1000, .8), name = "u-" + cid + ".jpg";
      await ghPut("web/photos/" + name, b64, "운영자: 쿠폰 이미지 " + cid); return GH.raw + "photos/" + name + "?v=" + Date.now().toString(36); }
    if (RT.assets){ const a = await RT.assets.upload(file); return a.url; }
  } catch(_) {}
  return "";
}
function bizRefresh(){ applyBiz(); BZ.msg = ""; pmChanged(); renderPlaces(); renderDeals(); }
document.addEventListener("change", e=>{ if (!e.target.dataset || !e.target.dataset.bizsample) return; OWNER.biz.sampleCoupons = e.target.checked; bizRefresh(); renderOps(); });
document.addEventListener("change", e=>{
  const k = e.target.dataset && e.target.dataset.biz; if (!k) return;
  const [grp, key] = k.split("."), v = e.target.type==="checkbox" ? e.target.checked : e.target.value.trim();
  OWNER.biz[grp][key] = v; bizRefresh(); renderOps();
});
document.addEventListener("click", e=>{
  const add = e.target.closest("[data-bizadd]"), del = e.target.closest("[data-bizdel]");
  if (!add && !del) return;
  const v = id => (document.getElementById(id)?.value || "").trim();
  if (del){ const [grp, i] = del.dataset.bizdel.split(":"); OWNER.biz[grp].splice(+i, 1); bizRefresh(); renderOps(); return; }
  if (add.dataset.bizadd==="sponsored"){
    if (!v("bzSpId")){ BZ.msg = "가게를 골라 주세요."; renderOps(); return; }
    OWNER.biz.sponsored.push({ id:v("bzSpId"), copy:v("bzSpCopy"), until:v("bzSpUntil") });
  } else {
    if (!v("bzCpShop") || !v("bzCpTitle")){ BZ.msg = "가게 이름과 쿠폰 내용을 적어 주세요."; renderOps(); return; }
    const cid = "cp-"+Date.now().toString(36), f = document.getElementById("bzCpImg")?.files?.[0];
    const item = { id:cid, shop:v("bzCpShop"), title:v("bzCpTitle"), cond:v("bzCpCond"), until:v("bzCpUntil"), region:v("bzCpRegion") };
    if (f){
      BZ.msg = "쿠폰 이미지를 올리는 중…"; renderOps();
      bizCouponImg(cid, f).then(url=>{ if (url) item.img = url; else BZ.msg = "이미지는 올리지 못했어요(쿠폰은 추가됨). 앱 운영자 로그인 상태에서 다시 해 보세요.";
        OWNER.biz.coupons.push(item); bizRefresh(); if (url) BZ.msg = "쿠폰과 이미지를 추가했어요."; renderOps(); });
      return;
    }
    OWNER.biz.coupons.push(item);
  }
  bizRefresh(); renderOps();
});
const APK = { open:false, busy:false, msg:"", tok:false };
function renderApkEntry(){
  const el = document.getElementById("apkEntry"); if (!el) return;
  el.hidden = !window.APK_BUILD; if (!window.APK_BUILD) return;
  if (state.isOps){ el.innerHTML = `<button class="linkbtn" data-apkops="logout">운영자 로그아웃</button><p class="meta">로그아웃하기 전까지 로그인이 유지돼요 · 수첩 버전 ${esc(String(window.NOTE_VER||"-"))}</p>`; return; }
  el.innerHTML = APK.open ? loginForm("apkLogin", APK) : `<button class="linkbtn" data-apkops="open">운영자</button>`;
}
function apkOpsOn(){ state.isOps = true; document.body.classList.add("opsmode"); renderTop(); renderOps(); renderGrid(); renderApkEntry(); }
document.addEventListener("click", e=>{
  const b = e.target.closest("[data-apkops]"); if (!b) return;
  const a = b.dataset.apkops;
  if (a==="open"){ APK.open = true; APK.msg = ""; renderApkEntry(); (document.getElementById("apkLoginId") || document.getElementById("apkLoginTok"))?.focus(); }
  if (a==="close"){ APK.open = false; renderApkEntry(); }
  if (a==="logout"){ if (!confirm("이 휴대폰에서 운영자 로그아웃할까요?")) return;
    sessionGhToken = "";
    state.isOps = false; APK.open = false; document.body.classList.remove("opsmode");
    if (state.tab==="ops") document.querySelector('[data-tab="places"]')?.click();
    renderTop(); renderOps(); renderGrid(); renderApkEntry(); }
});
// 켤 때마다 GitHub의 최신 운영 데이터(owner.json)를 확인한다. 더 새것(rev가 큰 것)일 때만 받아 다시 연다.
// 운영자(토큰 있음)는 캐시 없는 GitHub API로, 방문자는 raw 주소로 받는다. 수정 중이면 다시 열지 않고 알려만 준다.
const OSYNC = { pending:false };
async function ownerRemoteText(){
  if (ghToken()){
    const j = await ghApi("/contents/web/owner.json?ref=" + GH.branch);
    return decodeURIComponent(escape(atob(String(j.content||"").replace(/\s/g,""))));
  }
  const r = await fetch(GH.raw + "owner.json?t=" + Date.now(), { cache:"no-store" });
  return r.ok ? r.text() : null;
}
function ownerSync(){
  return ownerRemoteText().then(t=>{
    if (!t) return; t = t.trim(); const o = JSON.parse(t);
    const newer = ownerRev(o) > ownerRev(OWNER) || (window.APK_BUILD && !ownerRev(o) && !ownerRev(OWNER) && t !== (localStorage.getItem("gw_owner")||"").trim());
    if (!newer) return;
    try { localStorage.setItem("gw_owner", t); } catch(_) { return; }
    if (PM.dirty || PM.busy || PM.edit || HOTED.open){ OSYNC.pending = true; renderOps(); return; }
    softReload();
  }).catch(()=>{});
}
ownerSync();

