// 음식 사진 점수가 낮은 것(호수·건물·풍경 사진 등)은 가게 사진으로 쓰지 않는다 → 엉뚱한 사진이 붙는 문제 방지
function foodPhoto(p){ const f = FOOD_PH[p.id] || (p.gid && FOOD_PH["g-"+p.gid]) || null; return f && ((f.food != null && f.food < 0.5) || (f.fr != null && f.fr < 0.4) || !f.url) ? null : f; }
function photoFor(p){
  const op = OWNER.photos[p.id];
  if (op && op.url) return { url:op.url, credit:op.credit || "운영자 등록 사진", artist:"운영자 등록" };
  const up0 = state.uploads[p.id];
  if (up0 && up0.url) return { url:up0.url, credit:up0.credit || "운영자 등록 사진", artist:"운영자 등록" };
  const fp = (p.cat==="맛집" || p.cat==="카페") ? foodPhoto(p) : null;
  if (fp && fp.url) return { url:fp.url, credit:`사진: ${fp.by || "Google 지도 사용자"} · Google 지도`, artist:fp.by };
  const c = PHOTOS[p.id];
  if (c) { const tag = PHOTO_KIND[c.kind] || "";
    return { url:c.url, tag, example:!!tag, credit:`${tag ? tag+" · " : ""}사진: ${c.artist || "작가 미상"} · ${c.license} · `, link:c.page, linkText:"위키미디어 공용", artist:c.artist }; }
  const k = KTO_PHOTOS[p.id] || (p.img ? { url:p.img } : null);
  if (k){ const tag = PHOTO_KIND[k.kind] || "";
    return { url:httpsUrl(k.url), tag, example:!!tag, credit:(tag ? tag + " · " : "") + (k.credit || "사진: 한국관광공사 · 공공누리 제1유형(출처 표시)"), artist:k.by || "한국관광공사" }; }
  if (p.gphoto) return { url:p.gphoto.url, credit:`사진: ${p.gphoto.by} · Google 지도`, artist:p.gphoto.by };   // 구글 사진은 찍은 사람 표시 의무
  const up = state.uploads[p.id];
  if (up && up.url) return { url:up.url, credit:up.credit || "운영자 등록 사진", artist:"운영자 등록" };
  return null;
}
// 메인 화면 사진 줄: 고른 지역에서 사진 있는 곳을 동행 추천순으로 5장
function renderHeroPhotos(){
  const el = document.getElementById("heroPhotos"); if (!el) return;
  el.hidden = true; el.style.display = "none"; el.innerHTML = ""; return;   // 상단 장소 사진 줄은 쓰지 않는다(운영자 요청)
  const key = state.region+"|"+state.who+"|"+Object.keys(state.uploads).length+"|"+Object.keys(OWNER.photos).length;
  if (el.dataset.key===key) return; el.dataset.key = key;
  const list = regionPlaces().filter(p=>{ const ph = photoFor(p); return ph && !ph.example; }).sort((a,b)=>b.who[state.who]-a.who[state.who] || a.name.localeCompare(b.name)).slice(0,5);
  el.hidden = !list.length;
  el.innerHTML = list.length ? `<div class="heroph">${list.map(p=>{ const ph = photoFor(p);
      return `<figure><img src="${esc(ph.url)}" alt="${esc(p.name)}" loading="lazy"><figcaption><b>${esc(shortName(p))}</b>${esc(where(p))}</figcaption></figure>`; }).join("")}</div>
    <div class="herocredit">사진: ${list.map(p=>{ const ph = photoFor(p); return ph.link ? `<a href="${esc(ph.link)}" target="_blank" rel="noopener">${esc(ph.artist||"작가 미상")}</a>` : esc(ph.artist||""); }).join(", ")} · 출처와 라이선스는 각 장소 카드에 있어요</div>` : "";
}
function photoHtml(p){
  const ph = photoFor(p);
  if (!ph) return `<a class="nophoto" href="${esc(naverImg(photoQuery(p)))}" target="_blank" rel="noopener"><span class="npi">${catEmoji(p.cat)}</span><span class="npt"><b>아직 등록된 사진이 없어요</b><small>네이버에서 ‘${esc(photoQuery(p))}’ 사진 보기 ↗</small></span></a>`;
  return `<figure class="photo">${ph.tag?`<span class="phtag">${esc(ph.tag.replace(" 사진",""))}</span>`:""}<img class="thumb" src="${esc(ph.url)}" alt="${esc(ph.tag ? ph.tag+": "+p.name : p.name)}" loading="lazy" onerror="this.closest('figure').remove()">
    <figcaption>${esc(ph.credit)}${ph.link?`<a href="${esc(ph.link)}" target="_blank" rel="noopener">${ph.linkText}</a>`:""}</figcaption></figure>`;
}
const KTO_BASE = "https://apis.data.go.kr/B551011/KorService2";
// 강원(areaCode 32) 시·군 코드 → 이 앱의 지역 묶음
const KTO_SIGUNGU = { gangneung:[1], sokcho:[5,2], yangyang:[7], donghae:[3,4], pyeongchang:[15], jeongseon:[11,8], chuncheon:[13], wonju:[9], inje:[10], hongcheon:[16], hwacheon:[17] };
// 관광공사 '관광지'는 이름을 보고 바다·계곡·산·호수·강·숲·꽃·고원으로 나눈다 (맞는 게 없으면 '관광지')
function ktoCat(it){
  const t = String(it.contenttypeid)==="12" ? String(stripTags(it.title||"")).replace(/\s*\(.*?\)\s*/g,"").trim() : "";
  if (!t) return KTO_TYPES[it.contenttypeid] || "관광지";
  if (/계곡|폭포|소금강/.test(t)) return "계곡";
  if (/해변|해수욕장|해안|항$|포구|등대|방파제|해상/.test(t)) return "바다";
  if (/(산|봉|령)$|국립공원/.test(t) && !/동산$|(서원|서재|분교)$/.test(t)) return "산";
  if (/(호|호수|강|저수지|댐|습지)$|호수|강변|유원지/.test(t)) return "호수·강";
  if (/수목원|숲|정원|식물원|꽃|자작나무|휴양림|생태공원/.test(t)) return "숲·꽃";
  if (/목장|고원|평원|초원|데기/.test(t)) return "고원";
  return "관광지";
}
const KTO_TYPES = { 12:"관광지", 14:"역사", 28:"체험", 38:"소품샵", 39:"맛집", 32:"숙소" };
const stripTags = v => String(v||"").replace(/<br\s*\/?>/gi," ").replace(/<[^>]+>/g,"").replace(/[<>`]/g,"").replace(/"/g,"'").replace(/\s+/g," ").trim();
// 외부 자료(구글 지도·관광공사)는 누구나 이름을 바꿀 수 있으니, 화면에 넣기 전에 태그·따옴표를 없앤다(스크립트 실행 차단)
const cleanTxt = v => String(v ?? "").replace(/[<>`]/g, "").replace(/"/g, "'").replace(/[\u0000-\u001f]/g, " ").trim();
const cleanUrl = v => /^https:\/\/[^\s"'<>`]+$/i.test(String(v||"")) ? String(v) : "";
const cleanId = v => String(v ?? "").replace(/[^\w-]/g, "");
const normName = v => String(v||"").replace(/[\s·()（）]/g,"");
const ktoShort = t => t && t.length > 60 ? t.slice(0, 58) + "…" : t;
function ktoRegion(it){ return Object.keys(KTO_SIGUNGU).find(r=>KTO_SIGUNGU[r].includes(+it.sigungucode)); }
// 강원도 대략의 범위. 관광공사 자료에 좌표가 잘못 들어간 경우(예: 위도 19도)를 거른다
const inGangwon = (lat, lng) => lat > 36.9 && lat < 38.65 && lng > 127.0 && lng < 129.45;
function ktoToPlace(it){
  const region = ktoRegion(it), lat = +it.mapy, lng = +it.mapx;
  if (!region || !inGangwon(lat, lng)) return null;
  const rest = stripTags(it.restdate), closed = /연중무휴|없음/.test(rest) ? [] : WD.map((w,i)=>rest.includes(w+"요일")?i:-1).filter(i=>i>=0);
  return { id:"kto-"+cleanId(it.contentid), source:"kto", region, name:stripTags(it.title), cat:ktoCat(it),
    area:cleanTxt((String(it.addr1||"").split(" ")[1]||REG[region].name).replace(/(시|군)$/,"")), lat, lng, img:cleanUrl(it.firstimage),
    sig: stripTags(it.firstmenu) || ({맛집:"대표 메뉴는 현장 확인", 숙소:"숙박", 소품샵:"쇼핑", 역사:"문화·역사 시설", 체험:"레포츠·체험"})[KTO_TYPES[it.contenttypeid]] || "한국관광공사 추천 관광지",
    addr: stripTags(it.addr1), hours: ktoShort(stripTags(it.usetime)) || "현장 확인",
    fee: ktoShort(stripTags(it.usefee)) || "현장 확인", closed, closedNote: rest && !closed.length && !/연중무휴|없음/.test(rest) ? rest.slice(0,60) : "",
    tip: it.tel ? "문의 "+stripTags(it.tel) : "한국관광공사 TourAPI 정보예요.", who:{친구:2,연인:2,가족:2,혼자:2}, tags:["관광공사"] };
}
function ktoToStay(it){
  const region = ktoRegion(it);
  if (!region || !inGangwon(+it.mapy, +it.mapx)) return null;
  return { id:"kto-"+cleanId(it.contentid), source:"kto", region, name:stripTags(it.title), type:"숙박", area:cleanTxt((String(it.addr1||"").split(" ")[1]||"").replace(/(시|군)$/,"")) || REG[region].name,
    lat:+it.mapy, lng:+it.mapx, img: it.firstimage ? httpsUrl(it.firstimage) : "", price:"예약처 확인", why:stripTags(it.addr1) || "한국관광공사 등록 숙박", tip: it.tel ? "문의 "+stripTags(it.tel) : "관광공사 등록 정보예요.", q:stripTags(it.title) };
}
// 스냅샷 + 이 기기에서 불러온 캐시를 기존 목록에 합친다(이름이 같으면 직접 정리한 정보를 우선)
// 직접 정리한 장소의 좌표는 대략값이라, 같은 이름의 관광공사 장소가 있으면 공식 좌표·주소로 바꾼다
const baseName = n => normName(String(n||"").split(" · ")[0].replace(/\(.*?\)|（.*?）/g,""));
let OFFICIAL_FIX = 0;
function mergeKto(items){
  let n = 0;
  const names = new Set([...PLACES, ...LODGING].map(x=>normName(x.name)));
  const mine = new Map();
  [...PLACES, ...LODGING].forEach(x=>{ if (x.source!=="kto"){ mine.set(normName(x.name), x); if (!mine.has(baseName(x.name))) mine.set(baseName(x.name), x); } });
  // 관광공사 '쇼핑'에는 편의점·마트·일반 매장이 많아, 시장·특산물·공방 같은 여행객용 매장만 남긴다
  const shopOk = t => /시장|장터|오일장|5일장|고개|상회|건어물|약과|한과|특산|로컬|공방|기념품|아울렛|면세|양조|와이너리|치즈|초콜릿|커피|빵|떡|황태|젓갈|수산|어시장|농원|농장/.test(t) && !/마트|편의점|이마트|GS25|CU|세븐일레븐|다이소|안경|의료기|복권/.test(t);
  items.forEach(it=>{
    if (String(it.contenttypeid)==="38" && !shopOk(String(it.title||""))) return;
    const x = String(it.contenttypeid)==="32" ? ktoToStay(it) : ktoToPlace(it);
    if (x && DELETED.has(x.id)) return;
    const twin = x && (mine.get(normName(x.name)) || mine.get(baseName(x.name)));
    if (twin && !twin.__official && km(twin, x) < 3){
      twin.lat = x.lat; twin.lng = x.lng; twin.__official = true; OFFICIAL_FIX++;
      if (!twin.addr && it.addr1) twin.addr = stripTags(it.addr1);
    }
    // 계곡·해변처럼 넓은 곳은 출발점 좌표가 달라 3km를 넘기도 한다: 같은 지역·같은 이름이면 같은 곳으로 본다(가게는 지점이 달라 제외)
    const sameSpot = twin && (km(twin, x) < 3 || (twin.region===x.region && !["맛집","카페","숙소"].includes(twin.cat) && km(twin, x) < 20));
    if (!x || names.has(normName(x.name)) || sameSpot || [...PLACES, ...LODGING].some(y=>y.id===x.id)) return;
    names.add(normName(x.name)); n++;
    if (x.type) LODGING.push(x); else { PLACES.push(x); META[x.id] = { o:null, c:null, stay:60, cost:0 }; }
  });
  return n;
}
async function ktoFetch(key, region){
  const k = key.includes("%") ? key : encodeURIComponent(key), out = [];
  for (const sg of KTO_SIGUNGU[region]) for (const ct of Object.keys(KTO_TYPES)) {
    const u = `${KTO_BASE}/areaBasedList2?serviceKey=${k}&MobileOS=ETC&MobileApp=GangwonTrip&_type=json&numOfRows=20&pageNo=1&arrange=Q&areaCode=32&sigunguCode=${sg}&contentTypeId=${ct}`;
    const r = await fetch(u); if (!r.ok) throw new Error("HTTP "+r.status);
    const j = await r.json(), head = j && j.response && j.response.header;
    if (head && head.resultCode && head.resultCode!=="0000") throw new Error(head.resultMsg || head.resultCode);
    let items = (j.response && j.response.body && j.response.body.items && j.response.body.items.item) || [];
    if (!Array.isArray(items)) items = [items];
    out.push(...items);
  }
  return out;
}

