const fmt = m => { m = ((Math.round(m)%1440)+1440)%1440; return String(Math.floor(m/60)).padStart(2,"0")+":"+String(m%60).padStart(2,"0"); };
const fmtTripTime = m => {
  const raw = Math.round(Number(m) || 0);
  const dayOffset = Math.floor(raw / 1440);
  const mm = ((raw % 1440) + 1440) % 1440;
  const hh = String(Math.floor(mm / 60)).padStart(2,"0");
  const min = String(mm % 60).padStart(2,"0");
  return dayOffset > 0 ? `${hh}:${min} (+${dayOffset}일)` : `${hh}:${min}`;
};
