const HOT_N = 4;
const pickKey = () => state.region + "|" + state.who;
// 자동 추천: 동행 점수 → 사진 있는 곳 → 이름순(오늘 휴무인 곳 제외)
var KO_COLL = new Intl.Collator();   // localeCompare와 같은 순서, 훨씬 빠름
const autoHot = () => regionPlaces().filter(p=>status(p).cls!=="closed")
  .map(p=>[p, (p.who && p.who[state.who]) || 0, photoFor(p) ? 1 : 0])
  .sort((a,b)=>b[1]-a[1] || b[2]-a[2] || (KO_COLL || (KO_COLL = new Intl.Collator())).compare(a[0].name, b[0].name)).map(x=>x[0]);
// 운영자가 정한 순서가 있으면 그걸 먼저, 모자라면 자동 추천으로 채운다
function hotList(n = HOT_N){
  const fixed = (OWNER.picks[pickKey()] || []).map(byId).filter(p=>p && !HIDDEN.has(p.id) && inRegion(p));
  const rest = autoHot().filter(p=>!fixed.includes(p));
  return [...fixed, ...rest].slice(0, n);
}
const HOTED = { open:false };
function hotEditor(hot){
  if (!state.isOps) return "";
  if (!HOTED.open) return `<button class="linkbtn" data-hot="open" style="margin-top:8px">✎ 순서 정하기 (운영자)</button>`;
  const ids = hot.map(p=>p.id), mine = !!OWNER.picks[pickKey()];
  const cand = regionPlaces().filter(p=>!ids.includes(p.id)).sort((a,b)=>a.name.localeCompare(b.name));
  return `<div class="revbox pm" style="margin-top:10px"><h3>${regionLabel()} · ${({친구:"친구와",연인:"연인과",가족:"가족과",혼자:"혼자"})[state.who]} 가기 좋은 곳 순서</h3>
    <p class="meta">위·아래로 순서를 바꾸고, ✕로 빼고, 아래에서 장소를 골라 넣을 수 있어요. 지역·동행마다 따로 정해져요.${mine?"":" 지금은 자동 추천 순서예요."}</p>
    <ol class="pmlist">${hot.map((p,i)=>`<li><span class="pmno">${i+1}</span><span class="pmnm"><b>${esc(p.name)}</b><small>${esc(p.cat)} · ${esc(p.area)}</small></span>
      <span class="pmctl"><button data-hot="up" data-id="${p.id}" ${i===0?"disabled":""} aria-label="위로">▲</button><button data-hot="down" data-id="${p.id}" ${i===hot.length-1?"disabled":""} aria-label="아래로">▼</button><button data-hot="del" data-id="${p.id}" aria-label="빼기">✕</button></span></li>`).join("")}</ol>
    <div class="filters"><select id="hotAdd" aria-label="넣을 장소" style="max-width:100%"><option value="">장소 골라 넣기…</option>${cand.map(p=>`<option value="${p.id}">${esc(p.name)} · ${esc(p.cat)}</option>`).join("")}</select>
      <button class="btn ghost" data-hot="add">넣기</button></div>
    <div class="pmsave"><button class="btn" type="button" data-pm="save" ${PM.busy?"disabled":""}>${PM.busy?"저장하는 중…":"저장하고 공개"}</button>
      ${mine?`<button class="btn ghost" type="button" data-hot="auto">자동 추천으로 되돌리기</button>`:""}
      <button class="btn ghost" type="button" data-hot="close">닫기</button>
      ${PM.dirty?`<span class="meta">저장하지 않은 변경이 있어요.</span>`:""}${PM.msg?`<span class="okline">${esc(PM.msg)}</span>`:""}${PM.err?`<span class="errline">${esc(PM.err)}</span>`:""}</div>
  </div>`;
}
document.addEventListener("click", e=>{
  const b = e.target.closest("[data-hot]"); if (!b || !state.isOps) return;
  const a = b.dataset.hot, id = b.dataset.id, k = pickKey();
  let ids = hotList().map(p=>p.id);
  PM.msg = PM.err = "";
  if (a==="open"){ HOTED.open = true; }
  else if (a==="close"){ HOTED.open = false; }
  else if (a==="auto"){ delete OWNER.picks[k]; pmChanged(); }
  else {
    if (a==="up" || a==="down"){ const i = ids.indexOf(id), j = i + (a==="up" ? -1 : 1); if (i<0 || j<0 || j>=ids.length) return; [ids[i], ids[j]] = [ids[j], ids[i]]; }
    if (a==="del"){ ids = ids.filter(x=>x!==id); }
    if (a==="add"){ const v = document.getElementById("hotAdd")?.value; if (!v) return; ids = [v, ...ids.filter(x=>x!==v)]; }
    OWNER.picks[k] = ids.slice(0, HOT_N); pmChanged();
  }
  const y = window.scrollY; renderPlaces(); window.scrollTo({ top:y, behavior:"instant" });
});
