function stayPhotoHtml(l){
  const op = OWNER.photos[l.id], up = state.uploads[l.id], g = STAY_PH[l.id];
  const ph = (op && op.url) ? { url:op.url, credit:op.credit || "운영자 등록 사진" }
    : (up && up.url) ? { url:up.url, credit:up.credit || "운영자 등록 사진" }
    : g ? { url:g.url, credit:`사진: ${g.by || "Google 지도 사용자"} · Google 지도` }
    : l.img ? { url:l.img, credit:"사진: 한국관광공사 · 공공누리 제1유형(출처 표시)" } : null;
  if (!ph) return "";
  return `<figure class="photo"><img class="thumb" src="${esc(ph.url)}" alt="${esc(l.name)}" loading="lazy" onerror="this.closest('figure').remove()"><figcaption>${esc(ph.credit)}</figcaption></figure>`;
}
