  const el = document.getElementById("tab-transit"); if (!el) return;
  const town = state.region==="all" ? "강원" : REG[state.region].q;
  // 기차역은 위 열차 시간표 상자에서 역을 골라 보므로 아래 목록에서는 뺀다(겹침 방지).
  const here = TRANSIT.filter(t=>t.type!=="기차" && (state.region==="all"||t.region===state.region));
  const types = ["전체", ...["버스","공항"].filter(k=>here.some(t=>t.type===k))];
