function miniRow(p){ const ph = photoFor(p);
  return `<button class="mrow" data-detail="p:${esc(p.id)}">${ph?`<img src="${esc(ph.url)}" alt="" loading="lazy" onerror="this.replaceWith(Object.assign(document.createElement('span'),{className:'mico',textContent:'${catEmoji(p.cat)}'}))">`:`<span class="mico">${catEmoji(p.cat)}</span>`}
    <span class="mtx"><b>${esc(p.name)}</b><small>${esc(miniSub(p))}</small></span><span class="mgo">›</span></button>`; }
// 작은 줄 둘째 줄: 맛집·카페는 '요리 종류 · 대표 메뉴', 그 밖은 '분류 · 동네'
function sigShort(p){
  const t = String(p.sig||"").replace(/대표 메뉴는 현장 확인|현장 확인|정보 없음/g,"").replace(/^\s*(대표\s*메뉴|시그니처)\s*[:：]?\s*/,"").trim();
  if (!t) return "";
  // '일본 음식점', '로스터리 카페' 같은 업종 이름은 메뉴가 아니라서 뺀다
  const first = t.split(/[,，·/+]|\s+및\s+/).map(x=>x.trim()).filter(x=>x && !/(음식점|식당|레스토랑|전문점|라운지|카페|술집|주점|^바$)$/.test(x)).slice(0,2).join(", ");
  return first.length > 22 ? first.slice(0,21) + "…" : first;
}
function miniSub(p){
  if (p.cat==="맛집" || p.cat==="카페"){
    const k = foodSub(p), sig = sigShort(p);
    return [k==="기타" ? p.cat : k, sig || where(p)].filter(Boolean).join(" · ");
  }
  return `${p.cat} · ${where(p)}`;
}
