// ── 쿠폰 1회 사용 ──
// 쿠폰은 계정(로그인 시) 또는 이 기기에서 한 번만 쓸 수 있다. 사용 화면의 시계가 계속 움직여서 스크린샷 재사용을 직원이 가려내기 쉽다.
// 로그인하지 않은 방문자는 이 기기 저장소에만 기록돼서, 저장소를 지우면 다시 쓸 수 있다.
function isUsed(id){ return !!(state.used && state.used[id]); }
function couponExpired(c){ return !!(c && c.until && c.until < todayISOStr()); }
function redeemSlot(c){
  if (isUsed(c.id)){ const d = new Date(state.used[c.id]); return `<span class="tstamp">사용 완료<br>${isNaN(d) ? "" : (d.getMonth()+1)+"/"+d.getDate()}</span>`; }
  if (couponExpired(c)) return `<span class="tstamp">기간<br>만료</span>`;
  return `<button class="btn" type="button" data-redeem="${esc(c.id)}">사용하기</button>`;
}
let redeemTimer = null;
function closeRedeem(){ clearInterval(redeemTimer); redeemTimer = null; const b = document.getElementById("redeemBox"); if (b) b.remove(); }
function openRedeem(id){
  const c = PARTNER_COUPONS.find(x=>x.id===id); if (!c || isUsed(id) || couponExpired(c)) return;
  closeRedeem();
  const box = document.createElement("div"); box.id = "redeemBox"; box.className = "redeem-scrim";
  let armed = false;
  const tick = () => { const el = box.querySelector("#redeemClock"); if (el) el.textContent = new Date().toLocaleTimeString("ko-KR", { hour12:false }); };
  const draw = () => {
    box.innerHTML = `<div class="redeem-card" role="dialog" aria-modal="true" aria-labelledby="redeemTitle">
      <div><span class="redeem-shop">${esc(c.shop)}</span><h2 id="redeemTitle">${esc(c.title)}</h2><span class="redeem-shop">${esc(c.cond||"")}${c.until?` · ${esc(c.until)}까지`:""}</span></div>
      <div class="redeem-clock" id="redeemClock"></div>
      ${armed ? `<p class="redeem-warn">사용 완료로 바꾸면 되돌릴 수 없고, 이 쿠폰은 다시 쓸 수 없어요. 가게 직원이 확인했나요?</p>`
              : `<ol class="redeem-steps"><li>결제 전에 직원에게 이 화면을 보여 주세요.</li><li>시계가 움직이는지 직원이 확인해요.</li><li>혜택을 받은 뒤 아래 버튼을 눌러 주세요.</li></ol>`}
      <div class="redeem-row">
        ${armed ? `<button class="btn" type="button" data-rd="done">네, 사용 완료</button><button class="btn ghost" type="button" data-rd="back">아니요</button>`
                : `<button class="btn" type="button" data-rd="arm">사용 완료 처리</button><button class="btn ghost" type="button" data-rd="close">닫기</button>`}
      </div></div>`;
    tick(); const f = box.querySelector("[data-rd]"); if (f) f.focus();
  };
  box.addEventListener("click", e=>{
    e.stopPropagation();
    const b = e.target.closest("[data-rd]");
    if (!b){ if (e.target===box) closeRedeem(); return; }
    const a = b.dataset.rd;
    if (a==="close") closeRedeem();
    else if (a==="arm"){ armed = true; draw(); }
    else if (a==="back"){ armed = false; draw(); }
    else if (a==="done") finishRedeem(c);
  });
  box.addEventListener("keydown", e=>{ if (e.key==="Escape") closeRedeem(); });
  document.body.appendChild(box); draw();
  redeemTimer = setInterval(tick, 1000);
}
async function finishRedeem(c){
  if (isUsed(c.id)){ closeRedeem(); return; }
  const at = new Date().toISOString();
  state.used[c.id] = at; store.set("used", state.used);
  trackRev("redeem:"+c.id);
  trackEvent("coupon_redeem_complete", { couponId:c.id, shop:String(c.shop).slice(0,40), isDemo:!!(c.sample||c.demo) });
  closeRedeem(); renderCouponBook(); renderMy();
  try { await submitOrQueue("redeems", { coupon:c.id, shop:cleanTxt(c.shop).slice(0,40), title:cleanTxt(c.title).slice(0,40), at }); } catch(_){}
}
// 로그인한 계정의 사용 기록을 불러와서 다른 기기에서 쓴 쿠폰도 막는다
async function syncRedeems(){
  if (!(RT.db && RT.uid)) return;
  try {
    const s = await RT.db.doc("redeems/"+RT.uid).get();
    if (s.exists){
      ((s.data()||{}).items||[]).forEach(x=>{ if (x && x.coupon && !state.used[x.coupon]) state.used[x.coupon] = x.at || new Date().toISOString(); });
      store.set("used", state.used); renderCouponBook(); renderMy();
    }
  } catch(_){}
}
