const EXP_CATS = ["교통","숙박","식비","카페·간식","입장·체험","쇼핑","기타"];
const EXP = { list: store.get("exp", []), edit:null, msg:"", err:"", busy:false };
const saveExp = () => store.set("exp", EXP.list);
// 영수증 사진은 용량이 커서 이 기기의 IndexedDB에 따로 저장한다
const RC = { db:null, cache:{} };
function rcDb(){ return RC.db ? Promise.resolve(RC.db) : new Promise((ok, no)=>{ const r = indexedDB.open("gw_note", 1);
  r.onupgradeneeded = ()=>r.result.createObjectStore("receipts"); r.onsuccess = ()=>{ RC.db = r.result; ok(r.result); }; r.onerror = ()=>no(r.error); }); }
async function rcOp(mode, fn){ const db = await rcDb(); return new Promise((ok, no)=>{ const tx = db.transaction("receipts", mode), st = tx.objectStore("receipts"), q = fn(st); tx.oncomplete = ()=>ok(q && q.result); tx.onerror = ()=>no(tx.error); }); }
const rcPut = (id, data) => rcOp("readwrite", st=>st.put(data, id));
const rcGet = id => RC.cache[id] ? Promise.resolve(RC.cache[id]) : rcOp("readonly", st=>st.get(id)).then(v=>{ if (v) RC.cache[id] = v; return v; });
const rcDel = id => { delete RC.cache[id]; return rcOp("readwrite", st=>st.delete(id)); };
