function catEmoji(c){ return ({ 바다:"🌊", 산:"🏔️", 계곡:"🏞️", "호수·강":"🛶", "숲·꽃":"🌲", 고원:"🌾", 자연:"🌿", 카페:"☕", 맛집:"🍜", 역사:"🏯", 체험:"🎢", 소품샵:"🛍️", 관광지:"📍", 숙소:"🏨", 교통:"🚄" })[c] || "📍"; }
function stripItem(p, label){ const ph = photoFor(p);
  return `<button class="sitemc" data-detail="p:${esc(p.id)}"><span class="ic">${ph && !ph.example ? `<img src="${esc(ph.url)}" alt="" loading="lazy" onerror="this.remove()">` : ""}<i>${catEmoji(p.cat)}</i></span>${label?`<em>${esc(label)}</em>`:""}<b>${esc(shortName(p))}</b></button>`; }
function festIcon(f){ const n = f.name; return /해맞이|일출/.test(n) ? "🌅" : /산천어|빙어|송어|낚시/.test(n) ? "🎣" : /눈|얼음|겨울/.test(n) ? "❄️" : /커피/.test(n) ? "☕" : /벚꽃|유채|꽃|철쭉/.test(n) ? "🌸" : /단오/.test(n) ? "🎎" : /억새|단풍/.test(n) ? "🍂" : /바다|해변|여름|비치/.test(n) ? "🏖️" : /음식|먹|국수|오징어|한우|감자|메밀/.test(n) ? "🍲" : "🎉"; }
function festList(){
  const m = tripDay().getMonth()+1, nm = m%12+1;
  const pick = arr => arr.filter(f=>f.months.includes(m) || f.months.includes(nm)).sort((a,b)=>(a.months.includes(m)?0:1)-(b.months.includes(m)?0:1));
  return pick(FESTIVALS.filter(f=>state.region==="all" || f.region===state.region));   // 지역을 고르면 그 지역 축제만
}
function festStrip(){
  const L = festList(); if (!L.length) return "";
  const m = tripDay().getMonth()+1;
  return `<div class="stripwrap"><div class="sec-title"><h2>${m}월·${m%12+1}월 축제·행사</h2><span class="en">Festivals</span></div>
    <div class="strip">${L.map(f=>{ const pl = f.place && byId(f.place), ph = f.img ? { url:httpsUrl(f.img) } : (pl && photoFor(pl));
      return `<button class="sitemc" data-detail="f:${f.id}"><span class="ic">${ph && !ph.example ? `<img src="${esc(ph.url)}" alt="" loading="lazy" onerror="this.remove()">` : ""}<i>${festIcon(f)}</i></span><em>${esc(f.when)}</em><b>${esc(f.name.replace(/^(강릉|속초|양양|평창|정선|영월|춘천|원주|인제|홍천|화천|동해|삼척|고성)\s/,""))}</b></button>`; }).join("")}</div></div>`;
}
